import React from 'react';
import { useAchievements } from '../hooks/useData';

const Achievements: React.FC = () => {
  const { loading, error } = useAchievements();

  const milestones = [
    { rank: 'Influencer', sales: '₹150,000', reward: '₹10,000', icon: '🌟' },
    { rank: 'Star', sales: '₹500,000', reward: '₹30,000', icon: '⭐' },
    { rank: 'Elite', sales: '₹1,000,000', reward: '₹60,000', icon: '💎' },
    { rank: 'Crown', sales: '₹2,000,000', reward: '₹120,000', icon: '👑' },
    { rank: 'Platinum', sales: '₹5,000,000', reward: '₹300,000', icon: '🏆' },
    { rank: 'Global Icon', sales: '₹3,000,000,000', reward: '₹250,000,000', icon: '🌍' },
  ];

  if (loading) return <div className="text-center py-12">Loading achievements...</div>;
  if (error) return <div className="text-red-500 text-center py-12">{error}</div>;

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-bold text-gray-800">Achievements</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {milestones.map((milestone, idx) => (
          <div key={idx} className="card hover:shadow-lg transition">
            <div className="text-5xl mb-3">{milestone.icon}</div>
            <h3 className="text-xl font-bold text-gray-800">{milestone.rank}</h3>
            <p className="text-gray-600 text-sm mt-2">Target: {milestone.sales}</p>
            <p className="text-green-600 font-semibold mt-1">Reward: {milestone.reward}</p>
            <div className="w-full bg-gray-200 rounded-full h-2 mt-4">
              <div className="bg-blue-600 h-2 rounded-full w-1/3"></div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Achievements;
